import{_ as t,o as s,c as u,a3 as i,j as e,a as n}from"./chunks/framework.z_KJ15Ep.js";const a="/bilder/sekundarstufen/schueler-abitur-reiter.png",p=JSON.parse('{"title":"Den Abitur-Reiter für einzelne Prüflinge verwenden","description":"","frontmatter":{"title":"Den Abitur-Reiter für einzelne Prüflinge verwenden","source_pageid":1118,"source_revision":3696},"headers":[],"relativePath":"zeugnisse/sekundarstufen/abitur-schueler.md","filePath":"zeugnisse/sekundarstufen/abitur-schueler.md"}'),l={name:"zeugnisse/sekundarstufen/abitur-schueler.md"};function d(o,r,g,c,h,b){return s(),u("div",null,[...r[0]||(r[0]=[i('<h1 id="den-abitur-reiter-fur-einzelne-pruflinge-verwenden" tabindex="-1">Den Abitur-Reiter für einzelne Prüflinge verwenden <a class="header-anchor" href="#den-abitur-reiter-fur-einzelne-pruflinge-verwenden" aria-label="Permalink to &quot;Den Abitur-Reiter für einzelne Prüflinge verwenden&quot;">​</a></h1><p>Im Abitur-Reiter bearbeiten Sie die Prüfungsdaten eines einzelnen Prüflings. Die folgenden Abschnitte erläutern den Einstieg und die Prüfung der berechneten Ergebnisse.</p><h2 id="geltungsbereich-und-ablauf" tabindex="-1">Geltungsbereich und Ablauf <a class="header-anchor" href="#geltungsbereich-und-ablauf" aria-label="Permalink to &quot;Geltungsbereich und Ablauf&quot;">​</a></h2><p><strong>Geltungsbereich:</strong> Der beschriebene Ablauf mit vier Abiturfächern gehört zur bisherigen APO-GOSt. Für die Abgrenzung zur neuen Ordnung ab EF 2027/28 beachten Sie <a href="/zeugnisse/pruefungsordnungen.html">Prüfungsordnungen zuordnen</a>.</p><p>Bearbeiten Sie Abiturdaten individuell im Reiter Abitur. Die Übersicht erläutert Berechnungen, Eingriffsmöglichkeiten und Ergebnisse; der vollständige Ablauf ist separat beschrieben.</p><p><a href="/bilder/sekundarstufen/schueler-abitur-reiter.png"><img src="'+a+'" alt="Der Reiter Abitur bei Schülern der Q-Phase zur Verfügung." loading="lazy"></a></p><p><em>Der Reiter Abitur bei Schülern der Q-Phase zur Verfügung.</em></p><p>Wurden Schüler aus der Q-Phase ausgewählt, steht der Reiter <strong>Abitur</strong> unter <em>Schüler</em> zur Verfügung.</p>',8),e("div",{"data-hint-kind":"info",class:"info custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"info","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("circle",{cx:"12",cy:"12",r:"9"}),e("path",{d:"M12 11v6m0-10v.1"})]),n("Hinweis")]),e("p",null,[n("Dieser Artikel ist eine Übersicht über den Reiter "),e("em",null,"Abitur"),n(". Konsultieren Sie das Tutorial "),e("em",null,"Komplette Abiturberechnungen durchführen"),n(" für eine detaillierte Erklärung der Verwendung dieses Reiters beziehungsweise der zugehörigen Gruppenprozesse.")])],-1),i('<p>Der Ablauf ist, dass</p><ul><li>zuerst über <strong>Leistungsdaten holen</strong> die Leistungsdaten geholt werden.</li><li>Anschließend werden die Kurse algorithmisch markiert, SchILD versucht, möglichst positive Kurse einzubringen. Anschließend wird mit</li><li><strong>Zulassung berechnen</strong> eben dies getan. Das Ergebnis findet sich unten in der <strong>Auswertung</strong>.</li></ul><h2 id="berechnungsoptionen-und-ergebnisse-prufen" tabindex="-1">Berechnungsoptionen und Ergebnisse prüfen <a class="header-anchor" href="#berechnungsoptionen-und-ergebnisse-prufen" aria-label="Permalink to &quot;Berechnungsoptionen und Ergebnisse prüfen&quot;">​</a></h2><p>In die Berechnung der Zulassung kann noch über die <strong>Optionen</strong> links eingegriffen werden.</p><p><strong>Belegungs- und Markierungsfehler ignorieren</strong> übergeht die entsprechende Programmsperre. Klären und dokumentieren Sie vor der Verwendung, weshalb die rechtlichen Voraussetzungen trotz der Meldung erfüllt sind. Der Schalter ersetzt keine Zulassungsentscheidung und hebt keine Belegungspflicht auf.</p><p><strong>Zulassungsberechnung automatisch</strong> sogar dafür, dass bei einem manuellen Setzen und Entfernen von Markierungen auf Kursen die Zulassungsberechnung jedes mal erneut ausgeführt wird. Das Setzen und Entfernen von Markierungen wird über einen <code>Doppelklick</code> ausgeführt.</p><p>Mit <strong>2. Fremdsprache in der Sek. I manuell geprüft</strong> bestätigen Sie den Nachweis der zweiten Fremdsprache. Die Berechnung geht dann davon aus, dass diese Voraussetzung erfüllt ist. Das kann nötig sein, wenn eine Person erst zur EF oder Q1 an Ihre Schule gewechselt ist und die Leistungsdaten der Sekundarstufe I fehlen. Setzen Sie den Schalter erst, nachdem Sie die Vorzeugnisse oder anerkannte Nachweise geprüft haben.</p><p>Wenn die Zulassung erreicht wurden, lassen sich die über <strong>Prf. Pkt</strong> die Prüfungsergebnisse erfassen.</p><ul><li><p>Anschließend kann über <strong>Mündliche Prüfungen festlegen</strong> berechnet werden, ob das Abitur schon bestanden wurde. Falls nicht, werden die Haken bei <strong>MBP</strong> für das 1. bis 3. Abiturfach gesetzt. Eventuell kann ein Schüler eine freiwillige Prüfung wahrnehmen, dann ist der Haken bei <strong>MFP</strong> manuell zu setzen.</p></li><li><p>Bei mehreren mündlichen Prüfungen ist nun die Reihenfolge der Prüfungen über &#39;<em>MP RF</em> taktisch klug zu wählen.</p></li><li><p>Die Ergebnisse der mündlichen Prüfungen werden über <strong>MP Pkt.</strong> erfasst.</p></li><li><p><strong>Gesamtergebnis berechnen</strong> stößt die Berechnung des Gesamtergebnisses, also <strong>Abitur Bestanden</strong>, <strong>Punktsumme</strong> und <strong>Note</strong> an. Weiterhin wird angegeben, ab welcher Punktzahl ein <strong>Notensprung</strong> nach oben stattfinden würde.</p></li></ul><p>Schlussendlich lässt sich im Bereich der <em>Auswertung</em> auch der Schalter finden, mit dem ein <strong>Freiwilliger Rücktritt</strong> von der Abiturprüfung stattfindet.</p><p>Auf der linken Seite kann eine <strong>Besondere Lernleistung</strong> eingebracht werden. Hier wären <em>Art der Arbeit</em> (<em>Projektkurs</em> oder <em>externe Arbeit</em>) sowie deren <em>Titel</em> und die <em>Note</em> einzugeben.</p>',11),e("div",{"data-hint-kind":"info",class:"info custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"info","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("circle",{cx:"12",cy:"12",r:"9"}),e("path",{d:"M12 11v6m0-10v.1"})]),n("Hinweis")]),e("p",null,[n("Beachten Sie, dass ein Klick auf "),e("em",null,"Leistungsdaten holen"),n(" oder "),e("em",null,"Zulassung berechnen"),n(" alle schon später gemachten Eingaben zu den Prüfungen ohne weitere Warnung löscht.")])],-1),e("div",{"data-hint-kind":"important",class:"warning custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"important","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("circle",{cx:"12",cy:"12",r:"9"}),e("path",{d:"M12 7v6m0 4v.1"})]),n("Wichtig")]),e("p",null,"Die automatische Kursmarkierung und die Berechnung von Zulassung und Abiturergebnis unterstützen die Prüfung. Die Schule bleibt dafür verantwortlich, dass die Ergebnisse den geltenden Vorgaben entsprechen.")],-1),e("hr",null,null,-1),e("p",null,[e("a",{href:"https://schulverwaltungsinfos.nrw.de/svws/wiki/index.php?title=Abitur_(Sch%C3%BCler)",target:"_blank",rel:"noreferrer"},"Originalartikel im Wiki"),n(" · Quellrevision 3696.")],-1)])])}const m=t(l,[["render",d]]);export{p as __pageData,m as default};
